<template><div class="form-page"><div class="page-title"><div><p class="eyebrow">MENU EDITOR</p><h1>{{editing?'编辑菜品':'新增菜品'}}</h1></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form :model="form" label-position="top" class="dish-form"><el-form-item label="菜品名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="菜品介绍"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><div class="form-row"><el-form-item label="价格（円）" required><el-input-number v-model="form.price" :min="0" :precision="0"/></el-form-item><el-form-item label="分类" required><el-select v-model="form.category"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></el-form-item></div><div class="form-row"><el-form-item label="状态"><el-select v-model="form.status"><el-option label="上架" value="active"/><el-option label="下架" value="inactive"/></el-select></el-form-item><el-form-item label="显示顺序"><el-input-number v-model="form.sortOrder" :min="0" :precision="0"/></el-form-item></div><el-form-item label="菜品照片"><div class="image-upload"><img v-if="form.image" :src="imageUrl(form.image)"/><el-upload :show-file-list="false" :auto-upload="false" accept="image/jpeg,image/png,image/webp" :on-change="onFile"><el-button>{{editing?'更换照片':'选择照片'}}</el-button></el-upload><small>支持 JPG、PNG、WebP，最大 5MB</small></div></el-form-item><div class="form-actions"><el-button @click="$router.push('/admin/products')">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></div></el-form></div></template><script setup lang="ts">import {reactive,ref,computed,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,type Product} from '../api';import {activeStoreId} from '../storeContext';const route=useRoute(),router=useRouter(),editing=computed(()=>Boolean(route.params.id)),error=ref(''),saving=ref(false),file=ref<File|null>(null),categories=['推荐','主食','饮料','甜点'],form=reactive({name:'',description:'',price:0,category:'主食',image:'',status:'active',sortOrder:1});function imageUrl(s:string){return s.startsWith('/uploads')?`${new URL(import.meta.env.VITE_API_BASE_URL||'http://localhost:3000/api').origin}${s}`:s}function onFile(f:any){if(f.raw.size>5*1024*1024){error.value='图片不能超过5MB';return}if(!['image/jpeg','image/png','image/webp'].includes(f.raw.type)){error.value='仅支持 JPG、PNG、WebP';return}file.value=f.raw;form.image=URL.createObjectURL(f.raw);error.value=''}onMounted(async()=>{if(editing.value)try{const p:Product=(await api.get(`/products/${route.params.id}`)).data.data;Object.assign(form,p)}catch(e:any){error.value=e.message}});async function save(){if(!form.name.trim()){error.value='请填写菜品名称';return}saving.value=true;error.value='';try{const response=editing.value?await api.put(`/products/${route.params.id}`,form):await api.post('/products',{...form,storeId:activeStoreId.value});if(file.value){const body=new FormData();body.append('image',file.value);await api.post(`/products/${response.data.data.id}/image`,body)}ElMessage.success('保存成功');router.push('/admin/products')}catch(e:any){error.value=e.message}finally{saving.value=false}}</script>



